def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def fibonacci(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

def unique_preserve_order(values):
    seen = set()
    result = []
    for value in values:
        if value not in seen:
            seen.add(value)
            result.append(value)
    return result

def longest_word(words):
    if not words:
        return ""
    return max(words, key=len)

def median(values):
    values.sort()
    n = len(values)
    if n % 2 == 1:
        return values[n // 2]
    else:
        return (values[n // 2 - 1] + values[n // 2]) / 2

def balanced_brackets(text: str) -> bool:
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}

    for char in text:
        if char in pairs.values():
            stack.append(char)
        elif char in pairs:
            if not stack or stack.pop() != pairs[char]:
                return False
    return not stack

def group_by_length(words):
    length_dict = {}
    for word in words:
        word_length = len(word)
        if word_length not in length_dict:
            length_dict[word_length] = []
        length_dict[word_length].append(word)
    return length_dict

def is_subsequence(a, b):
    a_index = 0
    for i, char in enumerate(b):
        if a_index == len(a):
            break
        if a[a_index] == char:
            a_index += 1
    return a_index == len(a)

def run_length_encode(text):
    if not text:
        return []
    result = []
    count = 1
    for i in range(1, len(text)):
        if text[i] == text[i - 1]:
            count += 1
        else:
            result.append((text[i - 1], count))
            count = 1
    result.append((text[-1], count))
    return result

def first_nonrepeating(text: str) -> str:
    char_count = {}
    for char in text:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    for char in text:
        if char_count[char] == 1:
            return char

    return None
